  CONSTRAINT `financial_approvals_reviewed_by_foreign` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`),
  CONSTRAINT `financial_approvals_tuition_invoice_id_foreign` FOREIGN KEY (`tuition_invoice_id`) REFERENCES `tuition_invoices` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
