INSERT INTO `questions` VALUES (1,1,'What does CMS stand for in web development?','[\"Code Management Software\", \"Content Modeling System\", \"Content Management System\", \"Core Management Suite\"]','1',5,'2025-06-02 18:56:00','2025-06-06 05:15:38'),(2,1,'Which of the following is NOT a popular CMS platform?','[\"Wordpress\", \"Joomla\", \"Github\", \"Drupal\"]','2',5,'2025-06-02 18:57:55','2025-06-06 05:16:14'),(3,1,'In WordPress, what is a “theme”?','[\"A plugin that adds contact forms\", \"A template that controls the site\'s appearance\", \"A security module\", \"A coding language\"]','1',5,'2025-06-02 18:59:49','2025-06-06 05:17:04'),(4,1,'Which language is most commonly used to develop CMS platforms like WordPress, Joomla, and Drupal?','[\"PHP\", \"Java\", \"Python\", \"Ruby\"]','0',5,'2025-06-02 19:00:25','2025-06-06 05:17:33'),(5,1,'What is the purpose of a CMS?','[\"To edit video files\", \"To manage website content without coding\", \"To host e-commerce only\", \"To monitor user analytics\"]','1',5,'2025-06-02 19:01:17','2025-06-06 05:18:27'),(6,1,'In WordPress, which file is responsible for the main configuration?','[\"index.php\", \"wp-config.php\", \"config.html\", \"theme.json\"]','1',5,'2025-06-02 19:05:42','2025-06-06 05:19:10'),(7,1,'Which CMS is best known for e-commerce websites?','[\"Joomla\", \"Magento\", \"Ghost\", \"Medium\"]','1',5,'2025-06-02 19:07:32','2025-06-06 05:19:47'),(8,1,'In a CMS, what is a plugin or module?','[\"A file storage system\", \"A hosting service\", \"An add-on that extends functionality\", \"A default feature\"]','2',5,'2025-06-02 19:08:32','2025-06-06 05:20:21');
