DROP TABLE IF EXISTS `transcript_documents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `transcript_documents` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `transcript_request_id` bigint(20) unsigned DEFAULT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `department_id` bigint(20) unsigned NOT NULL,
  `verification_code` char(36) NOT NULL,
  `path` varchar(255) NOT NULL,
  `version` int(10) unsigned NOT NULL,
  `official` tinyint(1) NOT NULL DEFAULT 0,
  `status` varchar(255) NOT NULL DEFAULT 'valid',
  `result_versions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`result_versions`)),
  `sha256` varchar(64) DEFAULT NULL,
  `issued_by` bigint(20) unsigned DEFAULT NULL,
  `revoked_by` bigint(20) unsigned DEFAULT NULL,
  `revocation_reason` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `transcript_documents_verification_code_unique` (`verification_code`),
  UNIQUE KEY `transcript_documents_path_unique` (`path`),
  KEY `transcript_documents_transcript_request_id_foreign` (`transcript_request_id`),
  KEY `transcript_documents_user_id_foreign` (`user_id`),
  KEY `transcript_documents_department_id_foreign` (`department_id`),
  KEY `transcript_documents_issued_by_foreign` (`issued_by`),
  KEY `transcript_documents_revoked_by_foreign` (`revoked_by`),
  CONSTRAINT `transcript_documents_department_id_foreign` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`),
  CONSTRAINT `transcript_documents_issued_by_foreign` FOREIGN KEY (`issued_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `transcript_documents_revoked_by_foreign` FOREIGN KEY (`revoked_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `transcript_documents_transcript_request_id_foreign` FOREIGN KEY (`transcript_request_id`) REFERENCES `transcript_requests` (`id`),
  CONSTRAINT `transcript_documents_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

